// Helper to format phone number for WhatsApp international URL format (wa.me)
const formatWhatsAppNumber = (phone?: string | null): string => {
  if (!phone) return '';
  let digits = String(phone).replace(/\D/g, '');
  if (digits.length === 11 && digits.startsWith('0')) {
    digits = digits.slice(1);
  }
  if (digits.length === 10) {
    digits = `91${digits}`;
  }
  return digits;
};

// --- Types ---
enum OperationType {
  CREATE = 'create',
  UPDATE = 'update',
  DELETE = 'delete',
  LIST = 'list',
  GET = 'get',
  WRITE = 'write',
}

interface FirestoreErrorInfo {
  error: string;
  operationType: OperationType;
  path: string | null;
  authInfo: {
    userId: string | undefined;
    email: string | null | undefined;
    emailVerified: boolean | undefined;
    isAnonymous: boolean | undefined;
    tenantId: string | null | undefined;
    providerInfo: {
      providerId: string;
      displayName: string | null;
      email: string | null;
      photoUrl: string | null;
    }[];
  }
}

function handleFirestoreError(error: unknown, operationType: OperationType, path: string | null) {
  const errInfo: FirestoreErrorInfo = {
    error: error instanceof Error ? error.message : String(error),
    authInfo: {
      userId: auth.currentUser?.uid,
      email: auth.currentUser?.email,
      emailVerified: auth.currentUser?.emailVerified,
      isAnonymous: auth.currentUser?.isAnonymous,
      tenantId: auth.currentUser?.tenantId,
      providerInfo: auth.currentUser?.providerData.map(provider => ({
        providerId: provider.providerId,
        displayName: provider.displayName,
        email: provider.email,
        photoUrl: provider.photoURL
      })) || []
    },
    operationType,
    path
  }
  console.error('Firestore Error: ', JSON.stringify(errInfo));
  // Don't throw if it's a background sync error to prevent app crash
  if (operationType === OperationType.GET) {
    return errInfo;
  }
  throw new Error(JSON.stringify(errInfo));
}

/**
 * Creates a Firestore Timestamp from a YYYY-MM-DD string,
 * but combines it with the current local time to make it dynamic.
 * If the provided date matches today's local date, we return serverTimestamp()
 * or Timestamp.now() to ensure full precision.
 */
function getTimestampFromDateString(dateStr: string): Timestamp {
  if (!dateStr) return serverTimestamp() as Timestamp;
  
  try {
    const [year, month, day] = dateStr.split('-').map(Number);
    const now = new Date();
    
    // Check if the selected date is today
    const currentYear = now.getFullYear();
    const currentMonth = now.getMonth() + 1;
    const currentDay = now.getDate();
    
    if (year === currentYear && month === currentMonth && day === currentDay) {
      // If it's today, use Timestamp.now() for full real-time precision
      // We use now() instead of serverTimestamp() here because we often need 
      // the value immediately for local state or approval logic
      return Timestamp.now();
    }
    
    // If it's a different date, we still want the "time of recording"
    // so we set the date parts but keep current hours/minutes/seconds
    const targetDate = new Date();
    targetDate.setFullYear(year);
    targetDate.setMonth(month - 1);
    targetDate.setDate(day);
    // hours, minutes, seconds are already from 'new Date()' above
    
    return Timestamp.fromDate(targetDate);
  } catch (e) {
    console.error("Error creating timestamp from date string:", dateStr, e);
    return serverTimestamp() as Timestamp;
  }
}

/**
 * Resolves the sanction / disbursement / creation date of a loan accurately across Firestore Timestamps, Dates, and strings.
 * Core Unnati Rule: When a loan is recorded in a month, it cannot be due in the same month.
 * Its repayment starts strictly from the following month.
 */
export const getLoanSanctionDate = (l: Loan): Date => {
  const parseAnyDate = (val: any): Date | null => {
    if (!val) return null;
    if (typeof val.toDate === 'function') {
      try {
        const d = val.toDate();
        if (d instanceof Date && !isNaN(d.getTime())) return d;
      } catch {}
    }
    if (typeof val.seconds === 'number') {
      const d = new Date(val.seconds * 1000);
      if (!isNaN(d.getTime())) return d;
    }
    if (typeof val._seconds === 'number') {
      const d = new Date(val._seconds * 1000);
      if (!isNaN(d.getTime())) return d;
    }
    if (val instanceof Date) {
      if (!isNaN(val.getTime())) return val;
    }
    if (typeof val === 'string') {
      const parts = val.split(/[-/]/);
      if (parts.length === 3) {
        if (parts[0].length === 4) {
          // YYYY-MM-DD (e.g. 2026-10-11) - set hours to noon to prevent any negative timezone rollover
          const d2 = new Date(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]), 12, 0, 0);
          if (!isNaN(d2.getTime())) return d2;
        } else if (parts[2].length === 4) {
          // DD-MM-YYYY (e.g. 11-10-2026) - set hours to noon
          const d2 = new Date(Number(parts[2]), Number(parts[1]) - 1, Number(parts[0]), 12, 0, 0);
          if (!isNaN(d2.getTime())) return d2;
        }
      }
      const d = new Date(val);
      if (!isNaN(d.getTime())) return d;
    }
    return null;
  };

  const dates: Date[] = [];
  const appDate = parseAnyDate(l.approvedAt);
  if (appDate) dates.push(appDate);
  const creDate = parseAnyDate(l.createdAt);
  if (creDate) dates.push(creDate);
  const loanDate = parseAnyDate((l as any).loanDate);
  if (loanDate) dates.push(loanDate);
  const docDate = parseAnyDate((l as any).date);
  if (docDate) dates.push(docDate);
  const disbDate = parseAnyDate((l as any).disbursementDate || (l as any).disbursedAt);
  if (disbDate) dates.push(disbDate);

  if (dates.length > 0) {
    // When a loan has approval or creation timestamps, take the latest recording/sanction date
    return new Date(Math.max(...dates.map(d => d.getTime())));
  }
  return new Date();
};

/**
 * Core Unnati Rule: When a loan is recorded in a month, it cannot be due in the same month.
 * Its repayment starts strictly from the following month.
 * Returns true if the loan was recorded in targetMonth/targetYear or in a future month (hence payment hasn't started yet).
 */
export const isLoanRepaymentStartingInFuture = (loan: Loan, targetMonth: number, targetYear: number): boolean => {
  const sanctionDate = getLoanSanctionDate(loan);
  const sMonth = sanctionDate.getMonth() + 1; // 1-12
  const sYear = sanctionDate.getFullYear();
  // If loan was recorded in this target month or in a later month/year, repayment starts next month
  return (sYear > targetYear) || (sYear === targetYear && sMonth >= targetMonth);
};

/**
 * Helper to determine a loan's member-relative chronological loan number (e.g. Loan #1, Loan #2)
 * based on date of sanction/approval in ascending chronological order.
 * First loan sanctioned = Loan #1, second loan sanctioned = Loan #2, etc.
 */
export const getMemberLoanSequenceInfo = (loan: Loan, allLoansList: Loan[] = [], allUsersList: UserProfile[] = []) => {
  const targetUser = allUsersList.find(u => 
    isLoanMatchUser(loan, u) || 
    (loan.userId && (u.uid === loan.userId || u.id === loan.userId)) ||
    (loan.userEmail && u.email && u.email.toLowerCase().trim() === loan.userEmail.toLowerCase().trim())
  );
  const memberLoans = allLoansList.filter(l => 
    (targetUser && isLoanMatchUser(l, targetUser)) ||
    (loan.userId && l.userId === loan.userId) ||
    (loan.userEmail && l.userEmail && l.userEmail.toLowerCase().trim() === loan.userEmail.toLowerCase().trim())
  );

  // Sort chronologically ascending by sanction date
  const sortedMemberLoans = [...memberLoans].sort((a, b) => {
    const timeA = getLoanSanctionDate(a).getTime();
    const timeB = getLoanSanctionDate(b).getTime();
    return timeA - timeB;
  });

  const loanIndex = sortedMemberLoans.findIndex(l => l.id === loan.id);
  const loanNumber = loanIndex >= 0 ? loanIndex + 1 : 1;
  const totalMemberLoans = sortedMemberLoans.length;

  return {
    loanNumber,
    totalMemberLoans,
    hasMultipleLoans: totalMemberLoans > 1,
    label: `L#${loanNumber}`,
    fullLabel: `L#${loanNumber}`
  };
};

/**
 * Determines the chronological loan sequence number (#1, #2, etc.) for which a repayment was paid.
 * For members having multiple loans, this provides the exact PayTo# attribution.
 */
export const getRepaymentPayToNumber = (
  payment: LoanPayment,
  memberSortedLoans: Loan[],
  allLoansList: Loan[] = [],
  allUsersList: UserProfile[] = []
): number => {
  if (!memberSortedLoans || memberSortedLoans.length <= 1) return 1;

  // 1. Direct match on payment.loanId within member's chronologically sorted loans
  if (payment.loanId) {
    const directIdx = memberSortedLoans.findIndex(l => l.id === payment.loanId);
    if (directIdx >= 0) {
      return directIdx + 1;
    }

    // Try matching across all loans in case of different reference
    const matchedLoan = allLoansList.find(l => l.id === payment.loanId);
    if (matchedLoan) {
      const idxInSorted = memberSortedLoans.findIndex(l => l.id === matchedLoan.id);
      if (idxInSorted >= 0) return idxInSorted + 1;
      const seq = getMemberLoanSequenceInfo(matchedLoan, allLoansList, allUsersList);
      if (seq && seq.loanNumber) return seq.loanNumber;
    }
  }

  // 2. Heuristic fallback when payment.loanId is absent or unmatched:
  // Compare payment month/year to loan sanction dates
  const payYear = payment.year || 2026;
  const payMonth = payment.month || 1;

  // Find loans that were sanctioned on or before this payment month/year
  const eligibleLoans: { loan: Loan; index: number }[] = [];
  memberSortedLoans.forEach((l, idx) => {
    const sDate = getLoanSanctionDate(l);
    const sYear = sDate.getFullYear();
    const sMonth = sDate.getMonth() + 1;
    // Check if loan sanction date is on or before payment cycle month
    if (sYear < payYear || (sYear === payYear && sMonth <= payMonth)) {
      eligibleLoans.push({ loan: l, index: idx });
    }
  });

  if (eligibleLoans.length === 1) {
    return eligibleLoans[0].index + 1;
  }

  if (eligibleLoans.length > 1) {
    // If the latest eligible loan is active and earlier ones are closed/paid, attribute to latest
    const activeEligible = eligibleLoans.filter(el => el.loan.status === 'approved');
    if (activeEligible.length === 1) {
      return activeEligible[0].index + 1;
    }
    // Otherwise return the highest eligible index (latest sanctioned)
    return eligibleLoans[eligibleLoans.length - 1].index + 1;
  }

  return 1;
};

